package com.gamehub;
import com.gamehub.application.*;import com.gamehub.infrastructure.*;import org.junit.jupiter.api.Test;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
class TeamTournamentRegressionTest {
 @Test void captainCanRegisterEligibleTeamButOtherMemberCannot() throws Exception {Path p=Files.createTempFile("team-tournament-", ".db");try(Database db=new Database(p)){UserService us=new UserService(db);us.bootstrap("manager","password1");var manager=us.authenticate("manager","password1");var captain=us.registerCustomer("Captain","captain2@example.com","03001234101","password2");var member=us.registerCustomer("Member","member2@example.com","03001234102","password3");var o=new OperationsService(db);long team=o.createTeam(captain.id(),"Eligible Team");o.requestJoin(team,member.id());o.decideJoin(captain.id(),team,member.id(),true);long t=o.createTournament(manager.id(),"Team Cup","SINGLE_ELIMINATION","TEAM",4,0);o.changeTournamentStatus(manager.id(),t,"REGISTRATION_OPEN");assertThrows(SecurityException.class,()->o.registerTournamentTeam(t,member.id(),team));long registration=o.registerTournamentTeam(t,captain.id(),team);assertTrue(registration>0);assertThrows(IllegalStateException.class,()->o.registerTournamentTeam(t,captain.id(),team));}finally{Files.deleteIfExists(p);}}
}
